const band = ($flow.state.value_band || '').trim();
if (!band) return 'APPROVAL LOOKUP FAILED: value_band not set.';

const map = {
  iv_10000_or_less:
    'Department supervisor authorises the purchase. The policy requires no Finance Manager or Town Manager approval at this band (Section IV.A, Purchases for $10,000 or Less).',
  iv_over_10000:
    'Purchase orders over $10,000 require the approval of the Finance Manager, Town Manager, or a member of Mayor and Council (Section IV.B, Purchases greater than $10,000).',
  v_50000_or_less:
    'The Town Manager or Finance Manager signature requirement applies to V.A only; in this band the Mayor executes the contract after Council approval.',
  v_over_50000:
    'Council must approve at a public meeting, after which the Mayor executes the contract (Section V.B, Projects and Contracts valued greater than $50,000).'
};

return map[band] ||
  'The policy does not specify an approval authority for this case. Refer the supervisor to the Purchasing Manager.';

